function gCart(){try{return JSON.parse(localStorage.getItem('cart')||'{}')}catch(e){return{}}}function sCart(c){localStorage.setItem('cart',JSON.stringify(c))}function cartCount(c){return Object.values(c).reduce((n,it)=>n+it.quant,0)}function cartTotal(c){return Object.values(c).reduce((t,it)=>t+it.price*it.quant,0)}function updateBadge(){const el=document.getElementById('cart-count');if(!el)return;const n=cartCount(gCart());el.textContent=n>0?n:'';el.hidden=n===0}function setQuant(id,quant){const c=gCart();if(quant<=0){delete c[id]}else if(c[id]){c[id].quant=quant}sCart(c);updateBadge();renderCart()}function addToCart(id,name,price){const c=gCart();if(c[id]){c[id].quant++}else{c[id]={id:Number(id),name:name,price:Number(price),quant:1}}sCart(c);updateBadge()}function renderCart(){const list=document.getElementById('cart-list');if(!list)return;const c=gCart();const ids=Object.keys(c);list.innerHTML='';if(ids.length===0){list.innerHTML='<p class="empty-msg">El carrito está vacío</p>'}else{ids.forEach(id=>{const it=c[id];const row=document.createElement('div');row.className='cart-row';row.innerHTML='<span class="cart-row-name">'+it.name+'</span>'+'<span class="cart-row-price">₡'+it.price+'</span>'+'<span class="cart-row-qty">'+'<button type="button" class="btn btn-compact" data-qty-step="-1" data-id="'+id+'">−</button>'+'<span class="cart-row-qty-num">'+it.quant+'</span>'+'<button type="button" class="btn btn-compact" data-qty-step="1" data-id="'+id+'">+</button>'+'</span>'+'<span class="cart-row-subtotal">₡'+(it.price*it.quant)+'</span>'+'<button type="button" class="btn btn-compact" data-qty-remove data-id="'+id+'">Quitar</button>';list.appendChild(row)})}const totalEl=document.getElementById('cart-total');if(totalEl){totalEl.textContent='₡'+cartTotal(c)}const contBtn=document.getElementById('cart-continue');if(contBtn){contBtn.disabled=ids.length===0}}document.body.addEventListener('click',function(e){const add=e.target.closest('[data-cart-add]');if(add){addToCart(add.dataset.itemId,add.dataset.itemName,add.dataset.itemPrice);const old=add.textContent;add.textContent='Agregado ✓';add.disabled=true;setTimeout(()=>{add.textContent=old;add.disabled=false},900);return}const step=e.target.closest('[data-qty-step]');if(step){const c=gCart();const id=step.dataset.id;const d=Number(step.dataset.qtyStep);setQuant(id,(c[id]?c[id].quant:0)+d);return}const rm=e.target.closest('[data-qty-remove]');if(rm){setQuant(rm.dataset.id,0);return}});document.body.addEventListener('htmx:load',function(){updateBadge();renderCart()});
